/.well-known/agent-skills/index.json.body:
{
  "$schema": "https://schemas.agentskills.io/discovery/0.2.0/schema.json",
  "skills": [
    {
      "name": "spintax-authoring",
      "type": "skill-md",
      "description": "Turn finished copy into a spintax template that generates many grammatical variants. Use when asked to build a spintax template from scratch, spin existing text, design variable scoping across sites, or compose large templates from reusable blocks.",
      "url": "/.well-known/agent-skills/spintax-authoring/SKILL.md",
      "digest": "sha256:5d8f7ec470217235d7ebcfb879ef5c8ce24b4a578b45d0c1322dc19fb64998b8"
    },
    {
      "name": "spintax-engines",
      "type": "skill-md",
      "description": "Install and call an open-source spintax engine from JavaScript, PHP, Python or Object Pascal — @spintax/core on npm, spintax/core on Packagist, spintax-core on PyPI, and a Free Pascal engine on GitHub. Use when adding spintax rendering or validation to an application, choosing between the engines, or wiring a template pipeline into a runtime.",
      "url": "/.well-known/agent-skills/spintax-engines/SKILL.md",
      "digest": "sha256:adf43daef4c38bb83b7826c56a4b0112d7b01ad89cfa39582793f71fabceb774"
    },
    {
      "name": "spintax-syntax",
      "type": "skill-md",
      "description": "Write and debug spintax templates — {a|b} enumerations, [a|b|c] permutations, %variables%, #set/#def, {?VAR?then|else} conditionals and {plural n: form|form} agreement. Use when authoring, reviewing or fixing a spintax template, or when a template renders ungrammatical or unvarying output.",
      "url": "/.well-known/agent-skills/spintax-syntax/SKILL.md",
      "digest": "sha256:9422abcf393cc9da6f8b3c00c7e4db09c43c65818ca98e498db9977ad5414a1a"
    }
  ]
}

